 ['Project 13 of the chapter, run on three files in a temporary folder', "import csv, os, tempfile\nos.chdir(tempfile.mkdtemp())\nfor n, t in (('a.csv', 'h1,h2\\n1,2\\n3,4\\n'), ('b.csv', 'Hdr\\nx\\n'), ('notes.txt', 'not csv\\n')):\n    open(n, 'w').write(t)\nos.makedirs('headerRemoved', exist_ok=True)\nfor csv_filename in sorted(os.listdir('.')):\n    if not csv_filename.endswith('.csv'):\n        continue\n    print('Removing header from ' + csv_filename + '...')\n    csv_rows = []\n    csv_file_obj = open(csv_filename)\n    reader_obj = csv.reader(csv_file_obj)\n    for row in reader_obj:\n        if reader_obj.line_num == 1:\n            continue\n        csv_rows.append(row)\n    csv_file_obj.close()\n    csv_file_obj = open(os.path.join('headerRemoved', csv_filename), 'w', newline='')\n    csv_writer = csv.writer(csv_file_obj)\n    for row in csv_rows:\n        csv_writer.writerow(row)\n    csv_file_obj.close()\nprint(sorted(os.listdir('headerRemoved')), repr(open('headerRemoved/a.csv', newline='').read()), repr(open('a.csv').read()))", "Removing header from a.csv...\nRemoving header from b.csv...\n['a.csv', 'b.csv'] '1,2\\r\\n3,4\\r\\n' 'h1,h2\\n1,2\\n3,4\\n'"],
