 ["the chapter's XML text as printed does not parse, and pasted line breaks change the text", 'import xml.etree.ElementTree as ET\nprinted = """<person><name>Alice Doe</name><age>30</age>\n<programmer>true</programmer><car xsi:nil="true" xmlns:xsi=\n"http://www.w3.org/2001/XMLSchema-instance\\u201d/><address><street>\n100 Larkin St.</street><city>San Francisco</city><zip>94102</zip>\n</address><phone><phoneEntry><type>mobile</type><number>415-555-\n7890</number></phoneEntry><phoneEntry><type>work</type><number>\n415-555-1234</number></phoneEntry></phone></person>"""\ntry:\n    ET.fromstring(printed)\nexcept ET.ParseError as e:\n    print(\'ParseError:\', e)\nroot = ET.fromstring(printed.replace(\'\\u201d\', \'"\'))\nprint(root.tag, [c.tag for c in root])\nprint(repr(root.find(\'address/street\').text), repr(root.find(\'phone/phoneEntry/number\').text))', "ParseError: not well-formed (invalid token): line 3, column 45\nperson ['name', 'age', 'programmer', 'car', 'address', 'phone']\n'\\n100 Larkin St.' '415-555-\\n7890'"],
 ["the chapter's XML read as one piece: tags, text, children, iteration, filtering", 'import xml.etree.ElementTree as ET\nx = \'<person><name>Alice Doe</name><age>30</age><programmer>true</programmer><car xsi:nil="true" xmlns:xsi="http://www.w3.org/2001/XMLSchema-instance"/><address><street>100 Larkin St.</street><city>San Francisco</city><zip>94102</zip></address><phone><phoneEntry><type>mobile</type><number>415-555-7890</number></phoneEntry><phoneEntry><type>work</type><number>415-555-1234</number></phoneEntry></phone></person>\'\nroot = ET.fromstring(x)\nprint(root.tag, [c.tag for c in root])\nprint(root[0].tag, root[0].text, root[3].tag, root[3].text == None, root[4].tag, root[4][0].tag, root[4][0].text)\nfor elem in root:\n    print(elem.tag, \'--\', elem.text)\nprint([e.tag for e in root.iter()])\nfor elem in root.iter(\'number\'):\n    print(elem.tag, \'--\', elem.text)\nprint(root[3].attrib)\nprint(ET.tostring(root, encoding=\'utf-8\').decode(\'utf-8\'))', 'person [\'name\', \'age\', \'programmer\', \'car\', \'address\', \'phone\']\nname Alice Doe car True address street 100 Larkin St.\nname -- Alice Doe\nage -- 30\nprogrammer -- true\ncar -- None\naddress -- None\nphone -- None\n[\'person\', \'name\', \'age\', \'programmer\', \'car\', \'address\', \'street\', \'city\', \'zip\', \'phone\', \'phoneEntry\', \'type\', \'number\', \'phoneEntry\', \'type\', \'number\']\nnumber -- 415-555-7890\nnumber -- 415-555-1234\n{\'{http://www.w3.org/2001/XMLSchema-instance}nil\': \'true\'}\n<person xmlns:xsi="http://www.w3.org/2001/XMLSchema-instance"><name>Alice Doe</name><age>30</age><programmer>true</programmer><car xsi:nil="true" /><address><street>100 Larkin St.</street><city>San Francisco</city><zip>94102</zip></address><phone><phoneEntry><type>mobile</type><number>415-555-7890</number></phoneEntry><phoneEntry><type>work</type><number>415-555-1234</number></phoneEntry></phone></person>'],
 ["the chapter's XML built from scratch, and the text forms of tostring", "import xml.etree.ElementTree as ET\nperson = ET.Element('person')\nname = ET.SubElement(person, 'name'); name.text = 'Alice Doe'\nage = ET.SubElement(person, 'age'); age.text = '30'\nprogrammer = ET.SubElement(person, 'programmer'); programmer.text = 'true'\ncar = ET.SubElement(person, 'car')\ncar.set('xsi:nil', 'true')\ncar.set('xmlns:xsi', 'http://www.w3.org/2001/XMLSchema-instance')\naddress = ET.SubElement(person, 'address')\nstreet = ET.SubElement(address, 'street'); street.text = '100 Larkin St.'\nprint(ET.tostring(person, encoding='utf-8').decode('utf-8'))\nprint(type(ET.tostring(person)).__name__, type(ET.tostring(person, encoding='unicode')).__name__)\nprint(ET.tostring(person, encoding='unicode', short_empty_elements=False))\nET.indent(person)\nprint(ET.tostring(person, encoding='unicode'))", '<person><name>Alice Doe</name><age>30</age><programmer>true</programmer><car xsi:nil="true" xmlns:xsi="http://www.w3.org/2001/XMLSchema-instance" /><address><street>100 Larkin St.</street></address></person>\nbytes str\n<person><name>Alice Doe</name><age>30</age><programmer>true</programmer><car xsi:nil="true" xmlns:xsi="http://www.w3.org/2001/XMLSchema-instance"></car><address><street>100 Larkin St.</street></address></person>\n<person>\n  <name>Alice Doe</name>\n  <age>30</age>\n  <programmer>true</programmer>\n  <car xsi:nil="true" xmlns:xsi="http://www.w3.org/2001/XMLSchema-instance" />\n  <address>\n    <street>100 Larkin St.</street>\n  </address>\n</person>'],
 ['a document with two roots is not valid, and comments are not kept when parsing', "import xml.etree.ElementTree as ET\ntry:\n    ET.fromstring('<person><name>Alice Doe</name></person><person><name>Bob Smith</name></person>')\nexcept ET.ParseError as e:\n    print('ParseError:', e)\nprint([c.tag for c in ET.fromstring('<a><!-- note --><b/></a>')])", "ParseError: junk after document element: line 1, column 39\n['b']"],
 ['an Element with no children tests as false, with a warning since 3.12', "import warnings\nimport xml.etree.ElementTree as ET\ne = ET.fromstring('<a><b/></a>').find('b')\nwith warnings.catch_warnings(record=True) as w:\n    warnings.simplefilter('always')\n    print(bool(e), [x.category.__name__ for x in w])\nprint(e is not None, len(e))", "False ['DeprecationWarning']\nTrue 0"],
 ['a parsed namespace prefix becomes a URI in braces, and serialising moves the declaration', 'import xml.etree.ElementTree as ET\nr = ET.fromstring(\'<p><car xsi:nil="true" xmlns:xsi="http://www.w3.org/2001/XMLSchema-instance"/></p>\')\nprint(r[0].attrib)\nprint(ET.tostring(r, encoding=\'unicode\'))', '{\'{http://www.w3.org/2001/XMLSchema-instance}nil\': \'true\'}\n<p xmlns:xsi="http://www.w3.org/2001/XMLSchema-instance"><car xsi:nil="true" /></p>'],
 ['ElementTree reads a file and writes one with a declaration', "import io, os, tempfile\nimport xml.etree.ElementTree as ET\nos.chdir(tempfile.mkdtemp())\nopen('my_data.xml', 'w').write('<a><b>1</b></a>')\ntree = ET.parse('my_data.xml'); root = tree.getroot()\nroot[0].text = str(int(root[0].text) + 1)\ntree.write('out.xml', encoding='utf-8', xml_declaration=True)\nprint(open('out.xml', 'rb').read())", 'b"<?xml version=\'1.0\' encoding=\'utf-8\'?>\\n<a><b>2</b></a>"'],
 ['the DOM and SAX routes the chapter names, on one small document', "import xml.dom.minidom as md, xml.sax, xml.sax.handler\nprint([n.firstChild.data for n in md.parseString('<a><b>1</b><b>2</b></a>').getElementsByTagName('b')])\nclass H(xml.sax.handler.ContentHandler):\n    def __init__(self): self.ev = []\n    def startElement(self, n, a): self.ev.append('start ' + n)\n    def endElement(self, n): self.ev.append('end ' + n)\n    def characters(self, c): self.ev.append('text ' + c)\nh = H(); xml.sax.parseString(b'<a><b>1</b></a>', h); print(h.ev)", "['1', '2']\n['start a', 'start b', 'text 1', 'end b', 'end a']"],
 ['tomllib reads TOML, cannot write it, and reports where a parse failed', 'import tomllib\nt = tomllib.loads(\'name = "Alice Doe"\\nage = 30\\nprogrammer = true\\n[address]\\ncity = "San Francisco"\\n[[phone]]\\ntype = "mobile"\\n[[phone]]\\ntype = "work"\\n\')\nprint(t)\nprint(hasattr(tomllib, \'dumps\'))\ntry:\n    tomllib.loads(\'a = \')\nexcept tomllib.TOMLDecodeError as e:\n    print(type(e).__name__, e, e.lineno, e.colno)', "{'name': 'Alice Doe', 'age': 30, 'programmer': True, 'address': {'city': 'San Francisco'}, 'phone': [{'type': 'mobile'}, {'type': 'work'}]}\nFalse\nTOMLDecodeError Invalid value (at end of document) 1 5"],
 ["the chapter's practice program logic: one CSV per sheet, named from the workbook and the sheet", "import csv, io, os\nsheets = {'Sheet1': [['Fruit', 'Qty'], ['Apples', 73]], 'Totals': [['All', 73]]}\nout = {}\nfor excel_file in ['spam_data.xlsx', 'notes.txt']:\n    if not excel_file.endswith('.xlsx'):\n        continue\n    for sheet_name in sheets:\n        name = os.path.splitext(excel_file)[0] + '_' + sheet_name + '.csv'\n        s = io.StringIO(); w = csv.writer(s, lineterminator='\\n')\n        for row_num in range(1, len(sheets[sheet_name]) + 1):\n            w.writerow(sheets[sheet_name][row_num - 1])\n        out[name] = s.getvalue()\nprint(out)", "{'spam_data_Sheet1.csv': 'Fruit,Qty\\nApples,73\\n', 'spam_data_Totals.csv': 'All,73\\n'}"],
